import{_ as r,l,o as e,c as i,v as t,p as s,x as o,d as A,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"HANK","description":"","frontmatter":{"title":"HANK","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hank.md","filePath":"econ/hank.md","lastUpdated":1789023840000}'),h={name:"econ/hank.md"};function c(E,a,m,_,N,K){const n=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="hank" tabindex="-1">HANK <a class="header-anchor" href="#hank" aria-label="Permalink to &quot;HANK&quot;">​</a></h1><div class="epigraph"><p>异质、不完全市场与名义刚性接在一起时，货币与财政的传导不再只走欧拉的跨期替代，还走收入与流动性。</p><footer>—— Kaplan, Moll and Violante, Monetary Policy According to HANK, AER 2018</footer></div><p><a href="/econ/wealth-distribution-pareto">上一课</a>把厚尾与资本供给钉在实物不完全市场上。NK 的代表性 RANK 用欧拉把利率接到总需求。本课缺口是 <strong>HANK</strong>：同一套名义刚性，换上异质家庭与流动性资产结构。不重写 Calvo 推导，不重写帕累托机制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RANK：利率升 ⇒ 跨期替代 ⇒ 消费降，收入循环是次要的。Kaplan–Moll–Violante：大量家庭是贫流动性（富于非流动性资本、却缺流动性资产），MPC 高，消费跟的是现金流与工资，不是 \\(\\sigma(i-\\pi^e-\\rho)\\)。货币紧缩经一般均衡压劳动收入，再经高 MPC 放大——间接效应可主导直接欧拉效应。缺口是把 Aiyagari 分布与 NK 价格/工资粘性焊成同一均衡，而不是再估一个 SW。</p><p><span class="marginnote">Kaplan, Moll and Violante, <em>AER</em> 108(3), 2018, 697–743。Werning 对 RANK/HANK 的解析对照。Auclert 的充分统计（再分配渠道）。Gornemann–Kuester–Nakajima 更早的异质 NK。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>家庭：至少两种资产（流动性 vs 非流动性）或偶尔绑定的约束，劳动收入来自企业劳动需求。企业：Calvo 或 Rotemberg 定价。政策：泰勒规则。求解：稳态用 Aiyagari 装置；总量冲击用序列空间线性化或 KS 式定律。IRF 分解：直接（利率进欧拉、进抵押）vs 间接（工资、红利、税收、转移）。校准靶同时含微观 MPC 与宏观脉冲。</p>',8)),(e(),s(d,null,{default:o(()=>[p(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E5%88%A9%E7%8E%87%22%5D%20--%3E%20DIR%5B%22%E7%9B%B4%E6%8E%A5%3A%20%E6%AC%A7%E6%8B%89%20%2F%20%E6%8A%B5%E6%8A%BC%22%5D%0A%20%20I%20--%3E%20GE%5B%22GE%3A%20%E5%B7%A5%E8%B5%84%E4%B8%8E%E5%88%A9%E6%B6%A6%22%5D%0A%20%20GE%20--%3E%20INC%5B%22%E9%AB%98%20MPC%20%E5%AE%B6%E5%BA%AD%E7%9A%84%E6%94%B6%E5%85%A5%22%5D%0A%20%20DIR%20--%3E%20C%5B%22%E5%8A%A0%E6%80%BB%20C%22%5D%0A%20%20INC%20--%3E%20C%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 Smets–Wouters：SW 用习惯、规则拇指冲击模仿「消费跟收入」；HANK 把同一现象写成约束与分布。估计仍难，本课不把 HANK 贝叶斯当默认。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是加总 MPC 与收入循环。谁付利息、谁收红利、谁的工资动，决定再分配：Auclert 的渠道（未预期通胀对名义名义财富、利率对滚动债务）。若利润归富人、工资归高 MPC 劳动者，紧缩的间接效应更强。流动性资产供给（政府债、准备金）改变贫流动性份额，从而改变乘数——财政课下一课再放大这条。</p><p>RANK 不是 HANK 的 \\(\\sigma\\to\\infty\\) 极限这么简单：市场结构与谁持有债都要声明。</p><p><span class="marginnote">两资产是 KMV 的关键：一资产 HANK 往往让利率的直接收入效应（储蓄者变富）抵消太多。装置选择会改故事。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计最优 Taylor 系数。不把限价簿当流动性定义。企业异质与投资下一课序末才接。开放经济 HANK 不在此展开。诊断性预期与疏忽是预期单元，可叠加，不是本课。</p><p>后课默认：HANK = 不完全市场分布 + 名义刚性；传导以间接收入为主是可校准的结果，不是恒等式。下一课：把 MPC 的截面写成可测对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HANK 把异质家庭接到 NK 刚性上。</li><li>货币传导可被间接收入效应主导。</li><li>资产流动性结构决定谁是高 MPC。</li><li>出处：Kaplan, Moll and Violante, <em>AER</em> 2018。</li></ul>',10))])}const C=r(h,[["render",c]]);export{B as __pageData,C as default};
